Just made up a simple script for testing:
<details>
<summary>the test script (just attach to a `Node2D`)</summary>

```gdscript
@tool
extends Node2D

@export var initial_offset := Vector2(5, 5)
@export var size := Vector2(4, 4)
@export var border_width := 2.0
@export var separation := Vector2(1.0 / 8.0, 1)

func _process(delta):
	queue_redraw()

func _draw():
	var offset := initial_offset
	for rect_index in 8:
		var rect := Rect2(offset, size)
		var outer_size := rect.size + Vector2(border_width, border_width)
		draw_rect(rect, Color.FOREST_GREEN, false, border_width)
		
		var center := rect.get_center()
		
		var half_outer_size := 0.5 * outer_size
		var half_inner_size := 0.5 * (rect.size - Vector2(border_width, border_width))
		
		var outer_corners := [
			center + half_outer_size * Vector2(-1, -1),
			center + half_outer_size * Vector2(1, -1),
			center + half_outer_size * Vector2(1, 1),
			center + half_outer_size * Vector2(-1, 1),
		]
		var inner_corners := [
			center + half_inner_size * Vector2(-1, -1),
			center + half_inner_size * Vector2(1, -1),
			center + half_inner_size * Vector2(1, 1),
			center + half_inner_size * Vector2(-1, 1),
		]
		
		var is_not_full := border_width < rect.size.x and border_width < rect.size.y
		for i in 4:
			draw_line(outer_corners[i - 1], outer_corners[i], Color.ORANGE)
			if is_not_full:
				draw_line(inner_corners[i - 1], inner_corners[i], Color.ORANGE)
				draw_line(outer_corners[i], inner_corners[i], Color.ORANGE)
		for corner in outer_corners:
			draw_circle(corner, 0.1, Color.DARK_ORANGE)
		if is_not_full:
			for corner in inner_corners:
				draw_circle(corner, 0.1, Color.DARK_ORANGE)
	
		var rect_corners := [
			rect.position,
			rect.position + rect.size * Vector2(1, 0),
			rect.position + rect.size * Vector2(1, 1),
			rect.position + rect.size * Vector2(0, 1),
		]
		for i in 4:
			draw_line(rect_corners[i - 1], rect_corners[i], Color.DARK_RED)
		draw_circle(rect.position, 0.1, Color.DARK_RED)
		
		offset += separation + outer_size * Vector2.DOWN

```
</details>

